  10 const imageGeneratorSchema = z.object({
  11   prompt: z.string().min(1, 'Prompt is required.'),
  12   width: z.number().min(64).max(2048).default(800),
  13   height: z.number().min(64).max(2048).default(600),
  14   seed: z.number().optional(), // Make seed optional initially
  15 });
  16 
  17 type FormValues = z.infer<typeof imageGeneratorSchema>;
  18 
  19 interface HistoryItem extends FormValues {
  20   id: string;
  21   url: string;
  22   createdAt: string;
  23 }
  24 
  25 const API_BASE_URL = 'https://image.pollinations.ai/prompt/';
  26 
  27 export function useAIImageGeneratorLogic() {
  28   const { toast } = useToast();
  29   const [isLoading, setIsLoading] = useState(false);
  30   const [imageUrl, setImageUrl] = useState('');
  31   const [history, setHistory] = useState<HistoryItem[]>([]);
  32 
  33   const form = useForm<FormValues>({
  34     resolver: zodResolver(imageGeneratorSchema),
  35     defaultValues: {
  36       prompt: 'Arkan Logo',
  37       width: 800,
  38       height: 600,
  39       seed: undefined, // Initialize as undefined
  40     },
  41   });
  42 
  43   useEffect(() => {
  44     // Generate the seed only on the client side after hydration
  45     if (form.getValues('seed') === undefined) {
  46       form.setValue('seed', Math.floor(Math.random() * 10000000000));
  47     }
  48   }, [form]);
  49 
  50 
  51   useEffect(() => {
  52     try {
  53       const savedHistory = localStorage.getItem('ai-image-generator-history');
  54       if (savedHistory) {
  55         setHistory(JSON.parse(savedHistory));
  56       }
  57     } catch (error) {
  58       console.error("Failed to load history from local storage", error);
  59     }
  60   }, []);
  61 
  62   const saveHistory = (newHistory: HistoryItem[]) => {
  63     try {
  64       setHistory(newHistory);
  65       localStorage.setItem('ai-image-generator-history', JSON.stringify(newHistory));
  66     } catch (error) {
  67       console.error("Failed to save history to local storage", error);
  68       toast({ title: "Error", description: "Could not save image history.", variant: "destructive" });
  69     }
  70   };
  71 
  72 
  73   const onSubmit = async (data: FormValues) => {
  74     setIsLoading(true);
  75     setImageUrl('');
  76     try {
  77       const url = `${API_BASE_URL}${encodeURIComponent(data.prompt)}?width=${data.width}&height=${data.height}&nologo=poll&nofeed=yes&seed=${data.seed}`;
  78       
  79       // We don't need to fetch and convert to blob if the browser can display the URL directly
  80       // This also helps with downloading as we can just link to the URL
  81       setImageUrl(url);
  82 
  83     } catch (error) {
  84       console.error('Image generation failed:', error);
  85       toast({
  86         title: 'Image Generation Failed',
  87         description: error instanceof Error ? error.message : 'An unknown error occurred.',
  88         variant: 'destructive',
  89       });
  90     } finally {
  91       setIsLoading(false);
  92     }
  93   };
  94 
  95   const handleSave = () => {
  96     if (!imageUrl) {
  97       toast({ title: "No Image", description: "Please generate an image first before saving.", variant: "destructive" });
  98       return;
  99     }
 100     const currentValues = form.getValues();
 101     const newItem: HistoryItem = {
 102       id: uuidv4(),
 103       ...currentValues,
 104       url: imageUrl,
 105       createdAt: new Date().toISOString(),
 106     };
 107     const newHistory = [newItem, ...history].slice(0, 50); // Keep last 50
 108     saveHistory(newHistory);
 109     toast({ title: "Image Saved", description: "The image has been saved to your local history." });
 110   };
 111   
 112   const handleDelete = (id: string) => {
 113     const newHistory = history.filter(item => item.id !== id);
 114     saveHistory(newHistory);
 115     toast({ title: "Image Removed", description: "The image has been removed from your history." });
 116   };
 117 
 118   const handleDownload = async (url: string, fileName: string) => {
 119     try {
 120       const response = await fetch(url);
 121       if (!response.ok) throw new Error('Network response was not ok.');
 122       const blob = await response.blob();
 123       const link = document.createElement('a');
 124       link.href = URL.createObjectURL(blob);
 125       link.download = `${fileName}.png`;
 126       document.body.appendChild(link);
 127       link.click();
 128       document.body.removeChild(link);
 129       URL.revokeObjectURL(link.href);
 130     } catch (error) {
 131       console.error('Download failed:', error);
 132       toast({ title: 'Download Failed', description: 'Could not download the image.', variant: 'destructive' });
 133     }
 134   };
 135 
 136   const handleLoadFromHistory = (item: HistoryItem) => {
 137     form.reset(item);
 138     setImageUrl(item.url);
 139   };
 140 
 141   return {
 142     form,
 143     onSubmit,
 144     isLoading,
 145     imageUrl,
 146     history,
 147     handleSave,
 148     handleDelete,
 149     handleDownload,
 150     handleLoadFromHistory,
 151   };
 152 }
