  38 
  39       const reader = response.body?.getReader();
  40       const decoder = new TextDecoder();
  41 
  42       if (reader) {
  43         while (true) {
  44           const { done, value } = await reader.read();
  45           if (done) break;
  46 
  47           const chunk = decoder.decode(value);
  48           const lines = chunk.split('\n').filter(l => l.trim());
  49 
  50           for (const line of lines) {
  51             if (line.startsWith('data: ')) {
  52               const data = JSON.parse(line.slice(6));
  53               
  54               if (data.progress) {
  55                 setProgress(data.progress);
