   8  * @returns A promise that resolves to an object containing the image buffer and content type, or null on failure.
   9  */
  10 export async function getProxiedImageBuffer(imageUrl: string): Promise<ProxiedImage | null> {
  11   try {
  12     // Handle base64 data URLs directly on both client and server
  13     if (imageUrl.startsWith('data:')) {
  14       const response = await fetch(imageUrl);
  15       if (!response.ok) {
  16         console.warn(`Failed to fetch data URL. Status: ${response.statusText}`);
  17         return null;
  18       }
  19       const contentType = response.headers.get('Content-Type') || 'image/png';
  20       
  21       // NEW: Check if the data URL actually contains image data
  22       if (!contentType.startsWith('image/')) {
  23           console.warn(`Data URL does not represent an image. Content-Type: ${contentType}`);
  24           return null;
  25       }
  26 
  27       const buffer = await response.arrayBuffer();
  28       return { buffer, contentType };
  29     }
  30 
  31     // Check if running on the server or client
  32     if (typeof window === 'undefined') {
  33       // Server-side: Fetch the image directly
  34       if (!imageUrl.startsWith('http')) {
  35           console.warn(`[SERVER] Skipping non-absolute image URL: ${imageUrl}`);
  36           return null;
  37       }
  38       console.log(`[SERVER] Fetching image directly: ${imageUrl}`);
  39       const response = await fetch(imageUrl);
  40       if (!response.ok) {
  41         console.warn(`[SERVER] Failed to fetch image directly from ${imageUrl}. Status: ${response.status} ${response.statusText}`);
  42         return null;
  43       }
  44       const contentType = response.headers.get('Content-Type') || 'image/png';
  45 
  46       // NEW: Check content type before returning buffer
  47       if (!contentType.startsWith('image/')) {
  48         console.warn(`[SERVER] Fetched resource is not an image. Content-Type: ${contentType}. URL: ${imageUrl}`);
  49         return null;
  50       }
  51 
  52       const buffer = await response.arrayBuffer();
  53       return { buffer, contentType };
  54 
  55     } else {
  56       // Client-side: Use the API proxy
  57       const proxiedUrl = `/api/proxy/convert?url=${encodeURIComponent(imageUrl)}`;
  58       const response = await fetch(proxiedUrl);
  59       if (!response.ok) {
  60         console.warn(`[CLIENT] Failed to fetch proxied image from ${imageUrl}. Status: ${response.status} ${response.statusText}`);
  61         if (response.status === 405) {
  62           console.error("Method Not Allowed (405). Ensure your API route handles GET requests.");
  63         }
  64         return null;
  65       }
  66       const contentType = response.headers.get('Content-Type') || 'image/png';
  67       
  68       // NEW: Check content type before returning buffer
  69       if (!contentType.startsWith('image/')) {
  70         console.warn(`[CLIENT] Proxied resource is not an image. Content-Type: ${contentType}. URL: ${imageUrl}`);
  71         return null;
  72       }
  73       
  74       const buffer = await response.arrayBuffer();
  75       return { buffer, contentType };
  76     }
  77   } catch (error) {
  78     console.error(`Error fetching or processing image from ${imageUrl}:`, error);
  79     return null;
  80   }
  81 }
  82 
