  82     Object.entries(data).forEach(([key, value]) => {
  83       if (value !== null && value !== undefined && value !== '') {
  84         if (typeof value === 'boolean') {
  85           formData.append(key, value ? 'true' : 'false');
  86         } else if (value instanceof File) {
  87             formData.append(key, value);
  88         } else {
  89           formData.append(key, String(value));
  90         }
  91       }
  92     });
  93 
  94     mutation.mutate(formData);
  95   };
  96 
  97   const handleCopy = () => {
  98     if (!svgResult) return;
  99     navigator.clipboard.writeText(svgResult).then(() => {
 100       setIsCopied(true);
