   3 import { getAuthenticatedToken } from '@/lib/utils/authUtils';
   4 import type { User as FirebaseUser } from 'firebase/auth';
   5 
   6 export class ApiError extends Error {
   7   constructor(
   8     public message: string,
   9     public status: number,
  10     public details?: any
  11   ) {
  12     super(message);
  13     this.name = 'ApiError';
  14   }
  15 }
  16 
  17 interface ApiServiceOptions<T> {
  18   endpoint: string;
  19   method?: 'GET' | 'POST' | 'PUT' | 'DELETE' | 'PATCH';
  20   data?: T;
  21   token?: string; // Allow passing token directly
  22   firebaseUser?: FirebaseUser | null; // Or pass the user object
  23   headers?: Record<string, string>;
  24   isFormData?: boolean;
  25   responseType?: 'json' | 'blob' | 'text';
  26 }
  27 
  28 /**
  29  * A unified API service function to handle all client-server communication.
  30  * It automatically handles authentication, request body serialization, and response parsing.
  31  *
  32  * @param options - The configuration for the API request.
  33  * @returns A promise that resolves to the JSON response from the API.
  34  * @throws An ApiError if the request fails or the user is not authenticated when required.
  35  */
  36 export async function apiService<TRequest = any, TResponse = any>(
  37   options: ApiServiceOptions<TRequest>
  38 ): Promise<TResponse> {
  39   const {
  40     endpoint,
  41     method = 'GET',
  42     data,
  43     token: directToken,
  44     firebaseUser,
  45     headers = {},
  46     isFormData = false,
  47     responseType = 'json',
  48   } = options;
  49 
  50   let authToken = directToken;
  51 
  52   if (!authToken && firebaseUser) {
  53     authToken = await getAuthenticatedToken(firebaseUser);
  54   }
  55 
  56   const config: RequestInit = {
  57     method,
  58     headers: { ...headers },
  59   };
  60 
  61   if (authToken) {
  62     config.headers = {
  63       ...config.headers,
  64       'Authorization': `Bearer ${authToken}`,
  65     };
  66   }
  67 
  68   if (data) {
  69     if (isFormData) {
  70       // Don't set Content-Type for FormData, browser does it with boundary
  71       config.body = data as unknown as FormData;
  72     } else {
  73       (config.headers as Record<string, string>)['Content-Type'] = 'application/json';
  74       config.body = JSON.stringify(data);
  75     }
  76   }
  77 
  78   const response = await fetch(endpoint, config);
  79 
  80   if (!response.ok) {
  81     let errorData;
  82     try {
  83       errorData = await response.json();
  84     } catch {
  85       // If the response is not JSON, use the status text
  86       errorData = { message: response.statusText || 'An unknown error occurred.' };
  87     }
  88     throw new ApiError(errorData.message || response.statusText, response.status, errorData.details);
  89   }
  90 
  91   if (responseType === 'blob') {
  92     return (await response.blob()) as TResponse;
  93   }
  94 
  95   if (responseType === 'text') {
  96     return (await response.text()) as TResponse;
  97   }
  98 
  99   // Handle cases where the response might be empty (e.g., DELETE 204 No Content)
 100   const contentType = response.headers.get('content-type');
 101   if (contentType && contentType.includes('application/json')) {
 102     return response.json();
 103   }
 104   // Return an empty object or a success indicator for non-JSON responses
 105   return {} as TResponse;
 106 }
