      const result = await apiService<AppSettings, AppSettings>({
        endpoint: '/api/admin/settings',
        method: 'PUT',
        data,
        token,
      });

      return Result.ok(result);
    } catch (error: unknown) {
      return Result.fail(error as ApiError);
    }
  }
}
"}

